xpath.script:
(function () {
    'use strict';

    var _lastBid = null;
    var _lastTeamId = null;

    function fmtPts(n) {
        try { return Number(n || 0).toLocaleString(); }
        catch (e) { return String(n || 0); }
    }

    function hideLiveBid() {
        var root = document.getElementById('pjLiveBid');
        if (root) root.style.display = 'none';
        _lastBid = null;
        _lastTeamId = null;
    }

    function flashIfChanged(root, bid, teamId) {
        var changed = (_lastBid !== null) && (bid !== _lastBid || teamId !== _lastTeamId);
        _lastBid = bid;
        _lastTeamId = teamId;
        if (!changed || !root) return;
        root.classList.remove('is-updated');
        void root.offsetWidth;
        root.classList.add('is-updated');
    }

    function updateLiveBid(p) {
        var root = document.getElementById('pjLiveBid');
        if (!root) return;

        if (!p || p.state === 'sold' || p.state === 'unsold') {
            hideLiveBid();
            return;
        }

        var bid = (p.current_bid && p.current_bid > 0) ? Number(p.current_bid) : 0;
        var team = p.current_bid_team || null;
        var teamEl = document.getElementById('pjLiveBidTeam');
        var divider = document.getElementById('pjLiveBidDivider');
        var valEl = document.getElementById('pjLiveBidVal');
        var nameEl = document.getElementById('pjLiveBidName');
        var logoEl = document.getElementById('pjLiveBidLogo');

        root.style.display = 'flex';

        if (bid > 0) {
            root.classList.remove('is-waiting');
            if (valEl) valEl.textContent = fmtPts(bid);
            flashIfChanged(root, bid, team && team.id ? team.id : null);

            if (team && teamEl) {
                teamEl.style.display = 'flex';
                if (divider) divider.style.display = '';
                if (nameEl) nameEl.textContent = team.name || '';
                if (logoEl) {
                    if (team.logo_url) {
                        logoEl.src = team.logo_url;
                        logoEl.style.display = '';
                    } else {
                        logoEl.removeAttribute('src');
                        logoEl.style.display = 'none';
                    }
                }
            } else {
                if (teamEl) teamEl.style.display = 'none';
                if (divider) divider.style.display = 'none';
            }
        } else {
            root.classList.add('is-waiting');
            root.classList.remove('is-updated');
            _lastBid = 0;
            _lastTeamId = null;
        }
    }

    // Piggyback on the main projector poll — avoid a second /data request in production.
    window._pjOnPollResult = function (result) {
        updateLiveBid((result && result.player) || null);
    };
})();
